# retake 1 (15.11 night) of the takes that failed the fresh-eyes review of the raw video: ONE named change per clip (skill P2)
import json
E=json.load(open('entries.json')); R={}
def ch(c, rep=(), fit=None, face=None, addfit=None):
    e=json.loads(json.dumps(E[c]))
    for a,b in rep:
        assert a in e['story'], (c,a); e['story']=e['story'].replace(a,b)
    if fit is not None: e['fit']=fit
    if addfit: e['fit']=(e.get('fit','')+' '+addfit).strip()
    if face: e['face']=face
    R[c]=e
FACE_M="He faces the viewer for the whole clip and never turns sideways or shows his back."
FACE_F="She faces the viewer for the whole clip and never turns sideways or shows her back."
ch('kali_ti_hyp', [("sweeps the sword in one wide arc in front of her body at waist height, from one side to the other, her hips and shoulders turning with the cut","cuts one short arc with the sword in front of her body at waist height, her hips and shoulders turning with the cut, and ends it with a bent elbow, the blade pointing down in front of her")], fit="The sword stays in front of her body for the whole clip and is never stretched out to the side. The flames stay on the blade.")
