ch('nightmare_ti_atk', [("slashes the sickle in a short rising arc across his body, from his hip to the opposite shoulder, his torso twisting with the cut","makes one short rising cut with the sickle in front of his chest, from his hip to the middle of his chest, his shoulders leaning into the cut")], face=FACE_M)
ch('nightmare_bt_hyp', [("a violet glow runs along the blade during the cut and fades","the blade itself glows violet during the cut and the glow fades")], addfit="The glow stays on the blade itself: no streak of light in the air.")
