ch('thor_ti_sup', [("swings the hammer back beside his right hip with both hands, shifting his weight onto his back leg, his shoulders turning away","draws the hammer back beside his right hip with both hands, shifting his weight onto his back leg")], face="His chest and face are turned to the viewer for the whole clip.", fit="The hammer never rises above his chest. His skin, hair and armor keep their colours.")
