ch('thor_ti_hyp', [("blue-white sparks crackle only on the hammer head at each blow and fade","a few small blue-white sparks crackle on the hammer head itself at each blow and fade")], fit="The hammer never rises above his chin and leaves no trail of light. The sparks are small and stay on the hammer head. His face is visible in every frame.")
